// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IMailRelay {
    function sendMail(address to, bytes32 subject, bytes calldata body) external returns (bool);
}

contract EmailService is AccessControl, ReentrancyGuard {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant SENDER_ROLE = keccak256("SENDER_ROLE");
    bytes32 public constant RELAY_MANAGER_ROLE = keccak256("RELAY_MANAGER_ROLE");

    struct RelayConfig {
        address implementation;
        bool active;
        uint256 rateLimit;
        uint256 lastUsed;
    }

    struct SymLink {
        bytes32 targetId;
        address creator;
        uint256 createdAt;
        bool resolved;
    }

    mapping(bytes32 => RelayConfig) public relays;
    mapping(bytes32 => SymLink) public symlinks;
    mapping(address => uint256) public userNonces;
    mapping(address => mapping(uint256 => bool)) public processedMessages;

    event MailSent(address indexed from, address indexed to, bytes32 relayId);
    event RelayRegistered(bytes32 indexed relayId, address implementation);
    event SymLinkCreated(bytes32 indexed linkId, bytes32 indexed targetId);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(RELAY_MANAGER_ROLE, msg.sender);
    }

    function registerRelay(
        bytes32 relayId,
        address implementation,
        uint256 rateLimit
    ) external onlyRole(RELAY_MANAGER_ROLE) {
        require(implementation != address(0), "Invalid implementation");
        require(rateLimit > 0, "Invalid rate limit");
        relays[relayId] = RelayConfig({
            implementation: implementation,
            active: true,
            rateLimit: rateLimit,
            lastUsed: 0
        });
        emit RelayRegistered(relayId, implementation);
    }

    function createSymLink(
        bytes32 linkId,
        bytes32 targetId
    ) external onlyRole(RELAY_MANAGER_ROLE) {
        require(symlinks[linkId].creator == address(0), "Link exists");
        symlinks[linkId] = SymLink({
            targetId: targetId,
            creator: msg.sender,
            createdAt: block.timestamp,
            resolved: false
        });
        emit SymLinkCreated(linkId, targetId);
    }

    function resolveRelay(bytes32 relayId) public view returns (RelayConfig memory) {
        SymLink memory link = symlinks[relayId];
        if (link.creator != address(0)) {
            // Follow symlink - recursive resolution allows chains
            return resolveRelay(link.targetId);
        }
        return relays[relayId];
    }

    function _validateRateLimit(RelayConfig memory config) internal view returns (bool) {
        return (block.timestamp - config.lastUsed) >= config.rateLimit;
    }

    function _updateRelayUsage(bytes32 relayId) internal {
        // Update the original relay's lastUsed, not the resolved one
        SymLink memory link = symlinks[relayId];
        if (link.creator != address(0)) {
            // For symlinks, update the link's target usage
            _updateRelayUsage(link.targetId);
        } else {
            relays[relayId].lastUsed = block.timestamp;
        }
    }

    function sendEmail(
        bytes32 relayId,
        address recipient,
        bytes32 subject,
        bytes calldata body,
        uint256 nonce
    ) external nonReentrant onlyRole(SENDER_ROLE) {
        require(!processedMessages[msg.sender][nonce], "Nonce reused");
        require(recipient != address(0), "Invalid recipient");

        RelayConfig memory config = resolveRelay(relayId);
        require(config.active, "Relay not active");
        require(config.implementation != address(0), "Relay not found");
        require(_validateRateLimit(config), "Rate limited");

        processedMessages[msg.sender][nonce] = true;
        _updateRelayUsage(relayId);

        bool success = IMailRelay(config.implementation).sendMail(
            recipient, subject, body
        );
        require(success, "Send failed");

        emit MailSent(msg.sender, recipient, relayId);
    }

    function updateSymLinkTarget(
        bytes32 linkId,
        bytes32 newTargetId
    ) external onlyRole(RELAY_MANAGER_ROLE) {
        require(symlinks[linkId].creator != address(0), "Link not found");
        symlinks[linkId].targetId = newTargetId;
    }

    function deactivateRelay(bytes32 relayId) external onlyRole(ADMIN_ROLE) {
        relays[relayId].active = false;
    }

    function isRelayAccessible(bytes32 relayId) external view returns (bool) {
        RelayConfig memory config = resolveRelay(relayId);
        return config.active && config.implementation != address(0);
    }
}
